<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';
if(empty($_SESSION['admin_id']))redirect('login.php');
$pdo=db();$error='';$saved=isset($_GET['saved']);$dir=dirname(__DIR__).'/assets/uploads/site';
if(!is_dir($dir))@mkdir($dir,0755,true);
function site_value(PDO $pdo,string $key,string $default=''):string{$q=$pdo->prepare('SELECT setting_value FROM site_settings WHERE setting_key=?');$q->execute([$key]);$v=$q->fetchColumn();return $v===false?$default:(string)$v;}
$defaults=['hero_heading'=>"Good design\nmakes you look twice.",'hero_text'=>"Thoughtful visuals for brands, businesses and people with something to say. Let’s turn your next idea into a design that feels unmistakably yours.",'about_text'=>"I’m Hammad Ali, the graphic designer and founder behind Hammad Graphic. I create visual work for businesses, creators and growing brands — with a focus on clarity, personality and the details that make a design feel right.",'contact_email'=>'jabham786@gmail.com'];
$values=[];foreach($defaults as $key=>$default)$values[$key]=site_value($pdo,$key,$default);$values['portrait_path']=site_value($pdo,'portrait_path','');
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();foreach($defaults as $key=>$default){$values[$key]=trim((string)($_POST[$key]??''));if(text_length($values[$key])>3000)$error='Please keep each text field under 3000 characters.';}
if(!$error&&!filter_var($values['contact_email'],FILTER_VALIDATE_EMAIL))$error='Enter a valid contact email.';
if(!$error&&isset($_FILES['portrait'])&&($_FILES['portrait']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$f=$_FILES['portrait'];if($f['error']!==UPLOAD_ERR_OK)$error='Photo upload failed.';elseif($f['size']>5*1024*1024)$error='Portrait photo must be 5 MB or smaller.';else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)$error='Use JPG, PNG or WEBP for your portrait.';else{$name=bin2hex(random_bytes(18)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))$error='Could not save portrait photo.';else{$old=$values['portrait_path'];$values['portrait_path']=$name;if($old&&preg_match('/^[a-f0-9]{36}\.(jpg|png|webp)$/',$old))@unlink($dir.'/'.$old);}}}}
if(!$error){$s=$pdo->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($values as $k=>$v)$s->execute([$k,$v]);redirect('site-editor.php?saved=1');}}
?><!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Website editor — Hammad Graphic</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-dashboard"><main class="admin-container" style="max-width:900px"><div class="admin-title-row"><div><div class="eyebrow">WEBSITE CONTENT</div><h1>Website <em>editor.</em></h1><p>Update homepage text and your portrait without editing PHP files.</p></div><a class="button button-outline" href="index.php">Admin dashboard</a></div><?php if($saved):?><div class="alert alert-success">Website content saved.</div><?php endif;?><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><section class="admin-panel"><form method="post" enctype="multipart/form-data" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Homepage heading<textarea name="hero_heading" rows="3" maxlength="3000"><?=e($values['hero_heading'])?></textarea><small>Use a new line to split the heading.</small></label><label>Homepage introduction<textarea name="hero_text" rows="4" maxlength="3000"><?=e($values['hero_text'])?></textarea></label><label>About section text<textarea name="about_text" rows="5" maxlength="3000"><?=e($values['about_text'])?></textarea></label><label>Contact email<input type="email" name="contact_email" maxlength="190" value="<?=e($values['contact_email'])?>"></label><label>Profile photo <small>JPG / PNG / WEBP, max 5 MB</small><input type="file" name="portrait" accept="image/jpeg,image/png,image/webp"></label><?php if($values['portrait_path']):?><img src="../assets/uploads/site/<?=e($values['portrait_path'])?>" alt="Current profile photo" style="width:120px;height:140px;object-fit:cover"><?php endif;?><button class="button button-primary">Save website changes</button></form></section><p class="admin-footnote">Changes are shown on the public homepage immediately after saving. Portfolio posts remain Draft until you explicitly publish them.</p></main></body></html>